import { ref } from 'vue';

// Create your ErrorBoundary component here
const ErrorBoundary = {
  setup() {
    // Initialize error state with ref
    const error = ref(null);
    // Initialize error info state with ref
    const errorInfo = ref(null);

    // Implement defineErrorCaptured hook here
    defineErrorCaptured((err, info) => {
      error.value = err;
      errorInfo.value = info;
      return false;
    });
  },
  template: `
    <div>
      <slot v-if="!error" />
      <div v-else>
        <h2>Error caught by ErrorBoundary</h2>
        <p>{{ error.message }}</p>
        <pre>{{ errorInfo.componentStack }}</pre>
      </div>
    </div>
  `
};

